import type { FC } from 'react';
import { Slider } from '@/components/ui/slider';

interface QualitySliderProps {
  quality: number;
  onChange: (quality: number) => void;
}

const QualitySlider: FC<QualitySliderProps> = ({ quality, onChange }) => {
  return (
    <div>
      <label className="block text-xs font-medium text-muted-foreground mb-2">Quality: {quality}%</label>
      <Slider aria-label="Quality" value={[quality]} min={1} max={100} step={1} onValueChange={([v]) => onChange(v)} />
      <p className="text-xs text-muted-foreground mt-2 leading-relaxed">
        Higher quality keeps more detail but produces a larger file. Lower quality shrinks the file
        size, at the cost of visible compression artifacts — the result below updates live so you can
        find the right balance.
      </p>
    </div>
  );
};

export default QualitySlider;
